# Cette requete suit les relations en boucle et explose en cout.
# A chaque niveau, le serveur doit charger de plus en plus de donnees.
query RequeteAbusive {
  utilisateurs {           # tous les utilisateurs
    articles {             # tous leurs articles
      commentaires {       # tous les commentaires de chaque article
        auteur {           # l'auteur de chaque commentaire
          articles {       # ses articles... la boucle recommence
            commentaires {
              auteur {
                nom
              }
            }
          }
        }
      }
    }
  }
}
# Sans limite de profondeur ni de complexite, une seule requete
# de ce genre peut saturer la base de donnees et le service.
